import {EXCOMMUNICATIONS} from './excommunications.js?v=20261009-68';
import {TERRITORIES,describeEffects,describeEffect,PRIVILEGES} from './territories.js?v=20261009-68';
import {BUILDINGS,describeCost,describeBuildingCost} from './buildings.js?v=20261009-68';
import {CHARACTERS} from './characters.js?v=20261009-68';
import {VENTURES} from './ventures.js?v=20261009-68';
import {LEADERS,MARKETS} from './catalogs.js?v=20261009-68';
import {newGame,applyEffects,resolvePending,playLeader,discardLeaderForPrivilege,activateLeader,leaderRequirementMet} from './engine.js?v=20261009-68';
import {SOLO_CARD_REFERENCE} from './solo.js?v=20261009-68';
import {loadHighScores} from './highscores.js?v=20261009-68';
const $=id=>document.getElementById(id);
const MARKET_ICON={moneta:'moneta.png',monete:'moneta.png',soldo:'moneta.png',soldi:'moneta.png',legno:'legno.png',legni:'legno.png',pietra:'pietra.png',pietre:'pietra.png',servitore:'servitore.png',servitori:'servitore.png',favore:'favore.png',favori:'favore.png'};
const marketIcons=text=>String(text).replace(/(\d+)\s+(monet[ae]|soldi|soldo|legn[oi]|pietr[ae]|servitor[ei]|favor[ei])/gi,(_,n,name)=>`<span class="icon-reward"><b>${n}</b><img src="assets/${MARKET_ICON[name.toLowerCase()]}" alt="${name}" title="${name}"></span>`);
const esc=text=>String(text).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let ctx,started=false,filter={type:'territori',era:'1'};
export function initCatalogs(context){ctx=context;document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openCatalog(b.dataset.panel));$('home-button').onclick=showHome;$('start-game').onclick=openSetup;$('start-solo').onclick=openSoloSetup;$('resume-game').onclick=showGame;}
function showHome(){$('home-screen').hidden=false;$('game-screen').hidden=true;$('resume-game').hidden=!started;$('start-game').textContent=started?'Nuova partita multiplayer':'Partita multiplayer';}
function showGame(){$('home-screen').hidden=true;$('game-screen').hidden=false;}
function openSoloSetup(){ctx.modal(`<span class="eyebrow">PREPARAZIONE SOLITARIO</span><h2>Sfida Lorenzo</h2><p>Lorenzo usa otto familiari del proprio colore e può collocarne più di uno nella stessa torre.</p><label>Difficoltà <select id="solo-difficulty"><option value="easy">Facile · niente PV da carte o Consiglio</option><option value="medium" selected>Media · PV dal Consiglio</option><option value="hard">Difficile · PV da carte e Consiglio</option></select></label><label>Nome del giocatore <input id="solo-name" value="Giocatore"></label><button class="primary" id="confirm-solo">Inizia il solitario</button>`);$('confirm-solo').onclick=()=>{try{ctx.start({mode:'solo',playerCount:1,names:[$('solo-name').value.trim()||'Giocatore'],kinds:['human'],difficulty:$('solo-difficulty').value});started=true;ctx.dialog.close();showGame();}catch(error){document.getElementById('toast').textContent=`Errore: ${error.message}`;throw error;}};}
function openSetup(){ctx.modal(`<span class="eyebrow">PREPARAZIONE PARTITA</span><h2>Partita multiplayer locale</h2><p>Ogni giocatore usa la propria famiglia sullo stesso tavolo e svolge una mossa alla volta.</p><label>Numero di giocatori <select id="setup-count"><option>2</option><option>3</option><option>4</option></select></label><div id="setup-players"></div><button class="primary" id="confirm-setup">Inizia partita</button>`);const draw=()=>{$('setup-players').innerHTML=Array.from({length:Number($('setup-count').value)},(_,i)=>`<div class="setup-player"><label>Nome <input id="player-name-${i}" value="Giocatore ${i+1}"></label><label>Controllo <select><option>Umano</option><option disabled>Automa · prossimamente</option></select></label></div>`).join('');};$('setup-count').onchange=draw;$('confirm-setup').onclick=()=>{const count=Number($('setup-count').value),names=Array.from({length:count},(_,i)=>$(`player-name-${i}`).value.trim()||`Giocatore ${i+1}`);ctx.start({playerCount:count,names,kinds:Array(count).fill('human')});started=true;ctx.dialog.close();showGame();};draw();}
export function renderExtras(s){const pending=$('pending-effects');pending.hidden=!s.pending.length;pending.textContent=`Risolvi ${s.pending.length} effetti in sospeso →`;$('leader-count').textContent=`(${s.leaderHand.length})`;$('leader-hand').innerHTML='';s.leaderHand.forEach((c,index)=>{const ready=leaderRequirementMet(s,c),b=document.createElement('button');b.className=`card ${ready?'leader-ready':''}`;b.title=ready?'Requisiti soddisfatti: puoi giocare questo Leader':`Requisiti non ancora soddisfatti: ${c.requirement}`;b.innerHTML=`<img src="${c.image}" alt="${c.name}" loading="lazy">`;b.onclick=()=>{ctx.modal(`<span class="eyebrow">LEADER IN MANO · AZIONE LIBERA</span><h2>${c.name}</h2><img class="reference-image" src="${c.image}" alt="${c.name}"><dl class="effects"><dt>Requisito</dt><dd>${c.requirement}</dd><dt>Stato</dt><dd>${ready?'Requisiti soddisfatti':'Requisiti non ancora soddisfatti'}</dd><dt>Effetto · ${c.mode}</dt><dd>${c.effect}</dd></dl><div class="dialog-actions"><button id="discard-leader">Scarta per 1 favore</button><button class="${ready?'primary':''}" id="play-permanent-leader" ${ready?'':'disabled'}>Gioca Leader</button></div>`);$('play-permanent-leader').onclick=()=>{if(ctx.mutate(()=>playLeader(s,index,true))){ctx.dialog.close();ctx.render();}};$('discard-leader').onclick=()=>{if(ctx.mutate(()=>discardLeaderForPrivilege(s,index))){ctx.dialog.close();ctx.render();document.getElementById('pending-effects').click();}};};$('leader-hand').append(b);});const played=$('played-leaders');played.innerHTML='';s.playedLeaders.forEach((c,index)=>{const used=!!s.leaderUses?.[c.id],b=document.createElement('button');b.className=`card ${used?'leader-tapped':''}`;b.innerHTML=`<img src="${c.image}" alt="${c.name}" loading="lazy"><small>${c.name}${used?' · usato':''}</small>`;b.disabled=!c.oncePerRound||used;b.title=c.oncePerRound?(used?'Già usato in questo round':'Usa abilità una volta per round'):c.effect;b.onclick=()=>{if(ctx.mutate(()=>activateLeader(s,index))){ctx.render();}};played.append(b);});}
function imageDetail(c,title,note){const details=c.requirement?`<dl class="effects"><dt>Requisito</dt><dd>${c.requirement}</dd><dt>Effetto · ${c.mode}</dt><dd>${c.effect}</dd></dl><p>Trascrizione iniziale: indicami il nome del Leader per correggerla.</p>`:`<p>${note}</p>`;ctx.modal(`<span class="eyebrow">${title}</span><h2>${c.name}</h2><img class="reference-image" src="${c.image}" alt="${c.name}">${details}`);}
export function openCatalog(kind){if(kind==='development'){development();return;}if(kind==='solo'){soloCatalog();return;}if(kind==='highscores'){highscores();return;}if(kind==='excommunications'){const s=ctx.getState(),chosen=s.excommunications||[];ctx.modal(`<span class="eyebrow">PANNELLO DI CONTROLLO</span><h2>Elenco completo delle scomuniche</h2><p>All’inizio si estrae una tessera per livello. Le tessere segnate sono quelle della partita corrente.</p>${[1,2,3].map(level=>`<h3>Livello ${level}</h3><div class="vatican-grid">${EXCOMMUNICATIONS.filter(tile=>tile.level===level).map(tile=>`<article class="${chosen.some(x=>x.id===tile.id)?'chosen':''}"><h3>${tile.name}</h3><p>${tile.effect}</p><small>${chosen.some(x=>x.id===tile.id)?'Estratta in questa partita':'Non estratta'}</small></article>`).join('')}</div>`).join('')}<p>Soglie del Rapporto in Vaticano: 3 / 4 / 5 fede.</p>`);return;}const leader=kind==='leaders',items=leader?LEADERS:MARKETS;ctx.modal(`<span class="eyebrow">PANNELLO DI CONTROLLO · CONSULTAZIONE</span><h2>${leader?'Leader':'Tessere mercato'}</h2><p>${leader?'Mazzo Maiestas di 34 carte: retro e Leader barrati in rosso sono esclusi. Requisiti ed effetti sono trascritti per la verifica.':'Pila di 10 tessere aggiornata. A ogni turno si usano 2 spazi in 2 giocatori, 3 in 3 e 4 in 4. Le tessere vengono scartate a fine turno e gli scarti sono rimescolati quando la pila termina.'}</p><div class="catalog-grid" id="catalog-grid"></div>`);items.forEach(c=>{const b=document.createElement('button');b.className='catalog-card';b.innerHTML=`<img src="${c.image}" alt="${c.name}" loading="lazy"><strong>${c.name}</strong>${leader?'':`<p class="catalog-effect">${marketIcons(c.effect)}</p>`}<small>${c.id}</small>`;b.onclick=()=>{imageDetail(c,leader?'Leader':'Mercato',leader?'Immagine aggiornata. Gli effetti saranno automatizzati dopo la verifica.':c.effect);const back=document.createElement('button');back.textContent='← Torna al catalogo';back.onclick=()=>openCatalog(kind);$('dialog-content').append(back);};$('catalog-grid').append(b);});}
function highscores(){const records=loadHighScores(),section=(title,items)=>`<section class="score-section"><h3>${title}</h3>${items.length?items.map(scoreCard).join(''):'<p>Nessuna partita conclusa.</p>'}</section>`,solo=records.filter(record=>record.mode==='solo'),multi=records.filter(record=>record.mode==='multiplayer');ctx.modal(`<span class="eyebrow">ARCHIVIO RISULTATI</span><h2>Highscore</h2><p>I risultati vengono salvati su questo browser quando una partita viene conclusa.</p><div class="highscore-sections">${section('Solitario',solo)}${section('Multiplayer',multi)}</div>`);}
function scoreCard(record){const date=new Date(record.date).toLocaleString('it-IT',{dateStyle:'short',timeStyle:'short'}),outcome=record.mode==='solo'?(record.draw?'Pareggio':record.won?'Vittoria':'Sconfitta'):`${record.players.length} giocatori`,details=record.players.map(player=>`<div class="score-player ${player.winner||record.mode==='solo'&&!player.automa&&record.won?'winner':''}"><div><strong>${esc(player.name)}</strong><b>${player.total} PV</b></div><dl><dt>Durante la partita</dt><dd>${player.base}</dd><dt>Territori</dt><dd>${player.territories}</dd><dt>Edifici</dt><dd>${player.buildings}</dd><dt>Personaggi</dt><dd>${player.characters}</dd><dt>Imprese</dt><dd>${player.ventures}</dd><dt>Militari</dt><dd>${player.military}</dd><dt>Leader</dt><dd>${player.leaders} <small>(${player.leaderCount} carte)</small></dd><dt>Penalità</dt><dd>${player.penalties?`−${player.penalties}`:'0'}</dd></dl></div>`).join('');return`<article class="score-card"><div class="score-card-head"><div><strong>${outcome}</strong><small>${record.mode==='solo'?`Difficoltà ${esc(record.difficultyLabel)}`:'Partita multiplayer'} · ${date}</small></div></div><div class="score-players">${details}</div></article>`;}
function soloCatalog(){ctx.modal(`<span class="eyebrow">PANNELLO DI CONTROLLO · AUTOMA</span><h2>Carte di Lorenzo</h2><p>Seleziona una carta per confrontare fronte, retro, freccia, azioni e benefici alternativi.</p><div class="solo-catalog" id="solo-catalog"></div>`);for(const card of SOLO_CARD_REFERENCE){const b=document.createElement('button');b.className='solo-catalog-card';b.innerHTML=`<img src="${card.front}" alt="Fronte carta ${card.id}"><strong>Carta ${card.id}</strong><small>Retro: seleziona la colonna ${card.selector} della carta adiacente</small>`;b.onclick=()=>soloCardDetail(card);$('solo-catalog').append(b);}}
function soloCardDetail(card){ctx.modal(`<button id="solo-back">← Elenco carte automa</button><span class="eyebrow">AUTOMA · CARTA ${card.id}</span><h2>Carta di Lorenzo ${card.id}</h2><div class="solo-card-pair"><figure><img src="${card.front}" alt="Fronte carta ${card.id}"><figcaption>Fronte</figcaption></figure><figure><img src="${card.back}" alt="Retro carta ${card.id}"><figcaption>Retro</figcaption></figure></div><dl class="effects"><dt>Freccia del retro</dt><dd>Seleziona la colonna ${card.selector} del fronte della carta già rivelata e collocata accanto.</dd><dt>Destinazioni stampate</dt><dd>${card.targets.map((x,i)=>`${i+1}. ${x}${i+1===card.selector?' · selezionata':''}`).join('<br>')}</dd><dt>Relazione tra le carte</dt><dd>Il fronte fornisce le quattro possibili destinazioni. La freccia del retro di questa carta viene usata sulla carta fronte precedente, non sul proprio fronte.</dd><dt>Dado 1–2</dt><dd>${card.secondary[0]}</dd><dt>Dado 3–4</dt><dd>${card.secondary[1]}</dd><dt>Dado 5–6</dt><dd>${card.secondary[2]}</dd><dt>Alternativa se il familiare non può essere piazzato</dt><dd>${card.mainAlternative}</dd><dt>Alternativa se il blocco non può essere piazzato</dt><dd>${card.secondaryAlternative}</dd></dl><p>Indica il numero della carta e la voce da correggere.</p>`);$('solo-back').onclick=soloCatalog;}
function development(){ctx.modal(`<span class="eyebrow">PANNELLO DI CONTROLLO</span><h2>Carte sviluppo</h2><p>Confronta le immagini con gli effetti trascritti. Per Territori ed Edifici il valore indica il dado minimo necessario ad attivare raccolto o produzione.</p><div class="catalog-filters"><label>Tipologia<select id="catalog-type">${['territori','edifici','personaggi','imprese'].map(t=>`<option value="${t}" ${filter.type===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label><label>Epoca<select id="catalog-era">${['1','2','3','all'].map(e=>`<option value="${e}" ${filter.era===e?'selected':''}>${e==='all'?'Tutte':e}</option>`).join('')}</select></label></div><p id="catalog-count"></p><div class="catalog-grid" id="catalog-grid"></div>`);const draw=()=>{filter={type:$('catalog-type').value,era:$('catalog-era').value};const cards=ctx.cards.filter(c=>c.type===filter.type&&(filter.era==='all'||c.era===Number(filter.era)));$('catalog-count').textContent=filter.type==='territori'?`${cards.length} carte · verificate e confermate`:`${cards.length} carte · effetti trascritti, pronti per la verifica`;$('catalog-grid').innerHTML='';cards.forEach(c=>{const data=TERRITORIES[c.id]||BUILDINGS[c.id]||CHARACTERS[c.id]||VENTURES[c.id];const b=document.createElement('button');b.className='catalog-card';const status=c.type==='territori'?'✓ Confermata':!data?'Da implementare':data.implemented?'Effetti inseriti · da verificare':'Interpretazione da verificare';const value=c.type==='edifici'?data.activation:data.threshold;const activation=(c.type==='territori'||c.type==='edifici')?`<span class="catalog-status"><strong>Attivazione: ${value==='X'?'X':`dado ${value}+`}</strong></span>`:'';b.innerHTML=`<img src="${c.image}" alt="${c.name}" loading="lazy"><strong>${c.name}</strong><small>${c.id}</small>${activation}<span class="catalog-status">${status}</span>`;b.onclick=()=>catalogDetail(c);$('catalog-grid').append(b);});};$('catalog-type').onchange=draw;$('catalog-era').onchange=draw;draw();}
function catalogDetail(c){const t=TERRITORIES[c.id],b=BUILDINGS[c.id],p=CHARACTERS[c.id],v=VENTURES[c.id],data=t||b||p||v;const secondary=t?t.harvest:b?b.production:p?p.permanent:v?.endGame;const secondaryLabel=t?`Attivazione raccolto · dado ${t.threshold}+`:b?`Attivazione produzione · ${b.activation==='X'?'X':`dado ${b.activation}+`}`:p?'Effetto permanente':'Punteggio di fine partita';const military=v?.military?` oppure requisito ${v.military.required}, spendendo ${v.military.pay} punti militari`:'';const cost=t?'Nessun costo in risorse. Requisiti militari: 0 / 0 / 3 / 7 / 12 / 18.':b?describeBuildingCost(b):describeCost(data.cost)+military;ctx.modal(`<button id="catalog-back">← Elenco carte</button><div class="detail"><img src="${c.image}" alt="${c.name}"><div><span class="eyebrow">${c.id}</span><h2>${c.name}</h2><p>Fonte: ${c.source}</p>${data?`<dl class="effects"><dt>Costo</dt><dd>${cost}</dd><dt>Immediato</dt><dd>${describeEffects(data.immediate)}</dd><dt>${secondaryLabel}</dt><dd>${describeEffects(secondary)}</dd></dl>${data.note?`<p class="warning">${data.note}</p>`:''}<p>Trascrizione da verificare. Per una correzione indica il codice ${c.id}.</p><button id="test-immediate">Prova beneficio immediato</button><button id="test-action">Prova ${v?'punteggio':p?'effetto permanente':t?'raccolto':'produzione'}</button>`:'<p>Immagine importata dal nuovo file per epoca. Costi ed effetti di questa tipologia saranno implementati in seguito.</p>'}</div></div><section id="effect-test" hidden></section>`);$('catalog-back').onclick=development;if(data){$('test-immediate').onclick=()=>testEffects(c,data.immediate);$('test-action').onclick=()=>testEffects(c,secondary);}}
function testEffects(c,effects){const sandbox=newGame(ctx.cards,()=>0,LEADERS);for(const k in sandbox.resources)sandbox.resources[k]=20;sandbox.leaderHand=[];sandbox.leaderDeck=[...LEADERS];sandbox.collection=[c];applyEffects(sandbox,effects,c.name);const draw=()=>{const el=$('effect-test');el.hidden=false;el.innerHTML='<h3>Prova isolata</h3><p>Parte da 20 risorse di ogni tipo per consentire gli scambi. Non modifica la partita.</p><div class="test-resources">'+Object.entries(sandbox.resources).map(([k,n])=>`<span>${k}: <strong>${n}</strong></span>`).join('')+`<span>Leader pescati: <strong>${sandbox.leaderHand.length}</strong></span></div><div id="test-choices"></div>`;if(sandbox.pending.length){const pending=sandbox.pending[0];if(pending.kind==='manual'){$('test-choices').textContent=pending.text;return;}let options=pending.kind==='privilege'?PRIVILEGES:pending.kind==='trade'?[pending]:pending.options;if(pending.kind==='copyTerritory')options=sandbox.collection.filter(x=>x.type==='territori'&&x.id!=='territori-2-10');(options||[]).forEach((e,i)=>{const button=document.createElement('button');button.textContent=pending.kind==='copyTerritory'?e.name:describeEffect(e);button.onclick=()=>{resolvePending(sandbox,i);draw();};$('test-choices').append(button);});}};draw();}
